excels.excel:

EXPORT WITH SHEET="预算实际差异分析", HEADER=true,
    MAPPING={"a":"费用科目","b":"预算金额","c":"实际金额","d":"差异","e":"差异率","f":"结论"},
    FORMAT={"b":"#,##0.00","c":"#,##0.00","d":"#,##0.00","e":"0.00%"},
    FORMULAS={
        D2:'C2-B2',D3:'C3-B3',D4:'C4-B4',D5:'C5-B5',D6:'C6-B6',D7:'C7-B7',
        E2:'D2/B2',E3:'D3/B3',E4:'D4/B4',E5:'D5/B5',E6:'D6/B6',E7:'D7/B7',
        B8:'SUM(B2:B7)',C8:'SUM(C2:C7)',D8:'C8-B8',E8:'D8/B8'
    },
    STYLE={
        ROW 8:{bold:true,fillPattern:solid_foreground,fillForegroundColor:lightYellow,alignment:right,verticalAlignment:center},
        F3:{color:red,bold:true},
        F5:{color:red,bold:true},
        F7:{color:red,bold:true}
    }
